import javax.swing.*;
import java.awt.*;

public class AddForm {
    public static void main(String[] args) {
        JFrame f = new JFrame("Add Numbers");
        f.setLayout(new BorderLayout());

        JTextField a = new JTextField(8), b = new JTextField(8);
        JLabel result = new JLabel("Result: ");

        JPanel form = new JPanel(new GridLayout(3, 2));
        form.add(new JLabel("First:"));  form.add(a);
        form.add(new JLabel("Second:")); form.add(b);
        form.add(result);

        JButton add = new JButton("Add");
        JPanel south = new JPanel();
        south.add(add);

        add.addActionListener(e -> {
            try {
                double sum = Double.parseDouble(a.getText()) + Double.parseDouble(b.getText());
                result.setText("Result: " + sum);
            } catch (NumberFormatException ex) {
                JOptionPane.showMessageDialog(f, "Please enter numbers only");
            }
        });

        f.add(form, BorderLayout.CENTER);
        f.add(south, BorderLayout.SOUTH);
        f.setSize(300, 180);
        f.setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);
        f.setLocationRelativeTo(null);
        f.setVisible(true);
    }
}

